return items.map(item => {
  const price = item.json.price; // should already be parsed in previous step
  const capital = 50000;         // per trade capital
  const marginMultiplier = 5;    // intraday leverage

  if (!price || price <= 0) {
    item.json.calc = { error: "Invalid price" };
    return item;
  }

  // 1️⃣ Calculate max quantity without margin
  const qtyWithoutMargin = Math.floor(capital / price);

  // 2️⃣ Apply intraday margin
  const finalQty = qtyWithoutMargin * marginMultiplier;

  // 3️⃣ Calculate Stop Loss (0.65%) and Target (2%)
  const stopLossPrice = +(price * (1 - 0.0065)).toFixed(2);
  const targetPrice = +(price * (1 + 0.02)).toFixed(2);

  // 4️⃣ Attach to item
  item.json.calc = {
    price: price,
    qtyWithoutMargin: qtyWithoutMargin,
    finalQty: finalQty,
    stopLossPrice: stopLossPrice,
    targetPrice: targetPrice
  };

  return item;
});

const yahooFinance = require('yahoo-finance2').default;

const CAPITAL_PER_TRADE = 50000;
const MARGIN_MULTIPLIER = 5;
const STOPLOSS_PERCENT = 0.0065;
const TARGET_PERCENT = 0.02;
const TIMEOUT_MINUTES = 40;

// ===== MOCK BROKER API =====
function placeMarketBuy(symbol, qty, price) {
  console.log(`[BUY] ${qty} ${symbol} at INR ${price}`);
}

function placeMarketSell(symbol, qty, price, reason) {
  console.log(`[SELL] ${qty} ${symbol} at INR ${price} — Reason: ${reason}`);
}

// ===== FETCH LIVE OPEN PRICE =====
async function fetchCurrentOpen(symbol) {
  try {
    const yfSymbol = symbol.toUpperCase() + ".NS";
    const queryOptions = { interval: '1m', period1: '1d' };
    const result = await yahooFinance.historical(yfSymbol, queryOptions);
    if (result && result.length > 0) {
      const latest = result[result.length - 1];
      return parseFloat(latest.open.toFixed(2));
    }
  } catch (err) {
    console.log(`Error fetching live price for ${symbol}: ${err}`);
  }
  return null;
}

// ===== MAIN TRADE FUNCTION =====
async function executeTrade(symbol, entryPrice) {
  console.log(`\n[INFO] Received trade signal for ${symbol} at INR ${entryPrice}`);

  const qtyWithoutMargin = Math.floor(CAPITAL_PER_TRADE / entryPrice);
  const finalQty = qtyWithoutMargin * MARGIN_MULTIPLIER;

  const stopLoss = parseFloat((entryPrice * (1 - STOPLOSS_PERCENT)).toFixed(2));
  const target = parseFloat((entryPrice * (1 + TARGET_PERCENT)).toFixed(2));

  console.log(`[INFO] Calculated Stop Loss: INR ${stopLoss}, Target: INR ${target}, Qty: ${finalQty}`);

  const currentPrice = await fetchCurrentOpen(symbol);
  if (!currentPrice) {
    console.log("[ERROR] Could not fetch current price. Aborting trade.");
    return;
  }

  placeMarketBuy(symbol, finalQty, currentPrice);

  const startTime = new Date();
  console.log(`[INFO] Monitoring started at ${startTime.toLocaleTimeString()} for ${TIMEOUT_MINUTES} mins...`);

  const interval = setInterval(async () => {
    const livePrice = await fetchCurrentOpen(symbol);
    if (!livePrice) {
      console.log("[WARN] No live price, retrying...");
      return;
    }

    const now = new Date();
    if (livePrice <= stopLoss) {
      placeMarketSell(symbol, finalQty, livePrice, "Stop Loss Hit");
      clearInterval(interval);
    } else if (livePrice >= target) {
      placeMarketSell(symbol, finalQty, livePrice, "Target Hit");
      clearInterval(interval);
    } else if ((now - startTime) / 60000 >= TIMEOUT_MINUTES) {
      placeMarketSell(symbol, finalQty, livePrice, "Timeout 40 min");
      clearInterval(interval);
    } else {
      console.log(`[${now.toLocaleTimeString()}] ${symbol} Live Price INR ${livePrice} | SL INR ${stopLoss} | TGT INR ${target}`);
    }
  }, 20000); // 20-second interval
}

