  });
  return response.Open;
}

const startTime = Date.now();
const timeout = 40 * 60 * 1000; // 40 minutes
let currentPrice = null;

// 📝 Store logs to return at the end
const logs = [];

// 🟢 First log — BUY placed
logs.push({
  action: 'BUY',
  symbol: trade.symbol,
  qty: trade.finalQty,
  price: trade.price,
  time: new Date().toISOString()
});

while (true) {
  currentPrice = await fetchCurrentPrice.call(this);

  logs.push({
    action: 'FETCH',
    price: currentPrice,
    time: new Date().toISOString()
  });

  if (currentPrice >= trade.targetPrice) {
    logs.push({
      action: 'SELL',
      reason: 'TARGET',
      price: currentPrice,
      time: new Date().toISOString()
    });
    return [{ trade, logs }];
  }

  if (currentPrice <= trade.stopLossPrice) {
    logs.push({
      action: 'SELL',
      reason: 'STOPLOSS',
      price: currentPrice,
      time: new Date().toISOString()
    });
    return [{ trade, logs }];
  }

  if (Date.now() - startTime >= timeout) {
    logs.push({
      action: 'SELL',
      reason: 'TIMEOUT',
      price: currentPrice,
      time: new Date().toISOString()
    });
    return [{ trade, logs }];
  }

  await new Promise(resolve => setTimeout(resolve, 20000));
}

