const text = input.query.text || input.query.bigtext || "";
const trade = {};

// 1. Extract symbol
// This handles both "Buy M&M 28 OCT..." and "Buy YATHARTH at ₹..."
const symbolMatch = text.match(/Buy\s+([A-Za-z&]+)\b/);
trade.symbol = symbolMatch ? symbolMatch[1] : null;

// 2. Extract price (handles both cases)
const priceMatch = text.match(/at\s*₹\s*([\d.]+)/i);
trade.price = priceMatch ? parseFloat(priceMatch[1]) : null;

// 3. Calculate quantities and SL/Target if price is found
if (trade.price) {
  const capitalPerTrade = 50000;         // Fixed capital
  const qtyWithoutMargin = Math.floor(capitalPerTrade / trade.price);
  const finalQty = qtyWithoutMargin * 5; // 5x margin

  const stopLossPrice = trade.price * (1 - 0.0065); // 0.65% below
  const targetPrice = trade.price * (1 + 0.02);     // 2% above

  trade.qtyWithoutMargin = qtyWithoutMargin;
  trade.finalQty = finalQty;
  trade.stopLossPrice = parseFloat(stopLossPrice.toFixed(2));
  trade.targetPrice = parseFloat(targetPrice.toFixed(2));
} else {
  trade.qtyWithoutMargin = null;
  trade.finalQty = null;
  trade.stopLossPrice = null;
  trade.targetPrice = null;
}

return [
  {
    json: {
      ...input,
      trade
    }
  }
];

